"""Date parsing for invoice imports."""


def parse_date(text):
    """Parse an import date into a (year, month, day) tuple of ints.

    Supported formats are ISO and year-first slash-separated dates, plus
    day-first dotted dates.
    """
    parts = text.strip().replace("/", "-").replace(".", "-").split("-")
    if len(parts) != 3:
        raise ValueError(f"invalid date: {text!r}")

    first, second, third = parts
    if len(first) == 4:
        year, month, day = first, second, third
    elif len(third) == 4:
        day, month, year = first, second, third
    else:
        raise ValueError(f"invalid date: {text!r}")

    return (int(year), int(month), int(day))

{
  "summary": "Invoice date parsing now supports year-first slash dates and day-first dotted dates alongside ISO dates.",
  "ci_status": "green",
  "failing_tests": []
}

